// Делает явной декаду там, где она и так подразумевается общепринятой
// агрономической конвенцией ("до распускания почек" = начало месяца,
// "после угрозы заморозков" для майской высадки рассады = конец мая и
// т.п.), но не выражена словом, которое ловит detectDekada() в app.js.
// Не трогаем записи, где реальной привязки к части месяца нет (полив,
// "по мере созревания", "при обнаружении признаков") - для них "Весь
// месяц" честнее, чем придуманная декада.
//
// Правки применяются к тексту в средней полосе - через текстовое
// совпадение при пересборке региона автоматически подхватятся везде, где
// этот же текст переиспользуется (авто-сдвинутые записи регионов).

const path = require('path');
const XLSX = require('xlsx');

const ROOT = path.resolve(__dirname, '..', '..');
const XLSX_PATH = path.join(ROOT, 'garden-data.xlsx');

const wb = XLSX.readFile(XLSX_PATH);
const calRows = XLSX.utils.sheet_to_json(wb.Sheets['Calendar']);

// [oldText, newText] - точное совпадение по тексту записи средней полосы
